import{_ as t}from"./chunks/icon.DxQwhVtI.js";import{_ as a,a as s,b as n}from"./chunks/cards-177.DbNRxSpU.js";import{_ as i,o as r,c as o,a3 as l}from"./chunks/framework.BlfGB29P.js";const v=JSON.parse('{"title":"Automation Status Card","description":"Liste automatique, sélection par cases, exécutions et diagnostic des traces. Version 0.1.3, DE/EN/FR.","frontmatter":{"title":"Automation Status Card","description":"Liste automatique, sélection par cases, exécutions et diagnostic des traces. Version 0.1.3, DE/EN/FR."},"headers":[],"relativePath":"fr/projects/automation-status-card/index.md","filePath":"fr/projects/automation-status-card/index.md","lastUpdated":1794672141000}'),c={name:"fr/projects/automation-status-card/index.md"};function u(d,e,p,m,h,g){return r(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="automation-status-card" tabindex="-1">Automation Status Card <a class="header-anchor" href="#automation-status-card" aria-label="Permalink to &quot;Automation Status Card&quot;">​</a></h1><p><strong>HA 2026.11.0, 05/11/2026, <a href="/fr/collection/test-systems#testsystem-arm">système de test ARM (Pi 5)</a> :</strong> la version 0.1.3 passe l’affichage, l’activation/désactivation confirmée par HA, l’exécution en cours, la lecture des traces, la fin normale, les cases à cocher, tout sélectionner/désélectionner et le rechargement. Les exemples individuels Bubble/Mushroom s’affichent. Objets de test supprimés. Les erreurs et alertes de durée n’ont pas été provoquées à nouveau sous cette version de HA ; les résultats antérieurs restent distincts.</p><p><a href="/fr/collection/ha-2026-11-compatibility">Périmètre, résultats et problèmes ouverts</a>.</p><img src="'+t+`" width="80" height="80" alt="Automation Status Card"><p><strong>0.1.3 · DE / EN / FR · MIT</strong></p><p><a href="https://github.com/rockbaer2007/automation-status-card" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://github.com/rockbaer2007/automation-status-card/releases/tag/v0.1.3" target="_blank" rel="noreferrer">Télécharger 0.1.3</a> · <a href="https://opensource.ugso-software.de/fr/projects/automation-status-card/" target="_blank" rel="noreferrer">Documentation</a></p><p>Vérifié sur le système de test ARM (Pi 5) avec HA 2026.10.4 : carte de base 0.1.0 et sélection/diagnostics dans la version corrigée 0.1.3. Traces HA réelles, erreur, fin normale, alerte de durée, alerte désactivée, cases à cocher et sélection enregistrée vérifiées. <a href="https://github.com/rockbaer2007/automation-status-card/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Rapport et captures</a>.</p><p>Liste automatiquement toutes les entités <code>automation.*</code> disponibles pour l’utilisateur HA connecté, par ordre alphabétique. Huit lignes sont visibles par défaut ; les autres sont accessibles par défilement vertical. Les nouvelles automatisations et suppressions sont prises en compte automatiquement. Aucune bibliothèque de cartes supplémentaire n’est requise.</p><h2 id="installation-et-reglages" tabindex="-1">Installation et réglages <a class="header-anchor" href="#installation-et-reglages" aria-label="Permalink to &quot;Installation et réglages&quot;">​</a></h2><h3 id="hacs-marketplace" tabindex="-1">HACS / Marketplace <a class="header-anchor" href="#hacs-marketplace" aria-label="Permalink to &quot;HACS / Marketplace&quot;">​</a></h3><p>HACS / Marketplace : ajouter <code>https://github.com/rockbaer2007/automation-status-card</code> comme dépôt personnalisé <strong>Dashboard</strong> (<code>plugin</code>). Ressource : <code>/hacsfiles/automation-status-card/automation-status-card.js</code>. La compatibilité HACS ne signifie pas une inclusion au catalogue par défaut ; aucune installation Marketplace séparée n’a été testée. Ce n’est pas une application Supervisor. Ne pas charger simultanément les copies HACS et manuelle.</p><h3 id="installation-manuelle" tabindex="-1">Installation manuelle <a class="header-anchor" href="#installation-manuelle" aria-label="Permalink to &quot;Installation manuelle&quot;">​</a></h3><p>Sauvegardez HA. Copiez le fichier <code>automation-status-card.js</code> du paquet vers <code>/config/www/automation-status-card/automation-status-card.js</code>. Ajoutez <code>/local/automation-status-card/automation-status-card.js</code> dans <strong>Paramètres → Tableaux de bord → Ressources</strong>, type <strong>Module JavaScript</strong>, sans retirer les ressources existantes. Rechargez le tableau de bord et choisissez <strong>Automation Status Card</strong>.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:automation-status-card</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Automatisations</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">visible_rows</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allow_toggle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">language</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">auto</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>L’éditeur visuel permet de modifier le titre, les lignes visibles (entier 1–50), <strong>Autoriser la commutation</strong> et la langue (<code>auto</code>, <code>de</code>, <code>en</code>, <code>fr</code>). Un titre vide masque l’en-tête. La langue automatique suit HA, avec l’anglais comme repli.</p><p>Dans <strong>Afficher les automatisations</strong>, toutes les entrées sont initialement cochées : <strong>cochée = affichée</strong>, décochée = masquée uniquement dans cette carte. <strong>Tout sélectionner</strong> affiche toutes les entrées ; <strong>Tout désélectionner</strong> masque toutes les entrées actuellement répertoriées. Les nouvelles automatisations sont sélectionnées par défaut. La sélection est enregistrée par carte sans modifier les automatisations ni les autres cartes. Les entités décochées temporairement indisponibles restent répertoriées pour pouvoir être sélectionnées à nouveau. En YAML : <code>hidden_entities: [automation.mon_automatisation]</code> contient les identifiants décochés. Sans ce paramètre, le comportement précédent reste inchangé.</p><p>Le statut indique <strong>activée/désactivée</strong>, pas une exécution en cours. Le nom ouvre les détails HA. Lorsque la commutation est autorisée, chaque interrupteur active/désactive cette seule automatisation ; la carte ne déclenche pas ses actions. La désactivation utilise <code>stop_actions: false</code> pour ne pas arrêter explicitement une exécution existante. Les autorisations HA restent applicables ; l’affichage seul n’est pas une restriction d’accès.</p><p>Les états indisponibles/inconnus et une connexion interrompue interdisent la commutation. L’interrupteur est bloqué jusqu’à confirmation de l’état. Une erreur ou confirmation manquante est signalée, sans nouvelle tentative automatique ni succès supposé.</p><h2 id="executions-et-diagnostics" tabindex="-1">Exécutions et diagnostics <a class="header-anchor" href="#executions-et-diagnostics" aria-label="Permalink to &quot;Exécutions et diagnostics&quot;">​</a></h2><p>HA ne signale certaines interruptions que par <code>aborted</code>, notamment une condition fausse ou un arrêt explicite en erreur. Elles sont indiquées de façon neutre : <strong>Dernière exécution interrompue – vérifier la raison dans les traces HA</strong>, sans affirmer un succès ni un échec. Les durées issues des traces sont toujours plafonnées au temps observé par cette carte, afin qu’une différence d’horloge entre HA et le navigateur ne déclenche pas d’alerte prématurée.</p><p><code>show_health: true</code> (par défaut) ajoute le nombre d’exécutions et leur durée à partir de l’attribut HA <code>current</code>, indépendamment de l’activation. <code>runtime_warning_seconds: 300</code> avertit après cinq minutes ; <code>0</code> désactive l’alerte, maximum 604800 secondes (7 jours). Tous ces réglages figurent dans l’éditeur visuel. Une longue durée ne prouve pas un blocage : les délais et attentes peuvent être volontaires. Rien n’est arrêté ou redémarré automatiquement.</p><p>Avec une liste complète de traces correspondantes, la durée commence au début de la plus ancienne exécution active. Sinon, elle commence prudemment à l’observation par cette carte, avec une mention explicite. <code>last_triggered</code> seul ne sert pas de durée ; un déclenchement plus récent que la dernière demande de traces impose également cette estimation. Navigation, rechargement et déconnexion réinitialisent l’observation locale. Ce n’est pas une surveillance en arrière-plan.</p><p><code>check_traces: true</code> (par défaut) lit uniquement les résumés <code>trace/list</code> des automatisations, au maximum toutes les 30 secondes pour les administrateurs, avec un bouton d’actualisation manuelle. Aucune trace complète, variable ni configuration n’est demandée. La dernière exécution terminée est signalée en erreur uniquement si HA rapporte une erreur. Un arrêt normal ou une condition fausse n’est pas automatiquement une erreur. Une exécution terminée plus récente sans erreur signalée remplace l’ancienne indication d’erreur. L’horodatage figure dans l’infobulle ; le nom ouvre toujours les détails HA.</p><p>L’absence de droits administrateur, d’identifiant d’automatisation ou de traces, une API non compatible et les erreurs de connexion indiquent des diagnostics indisponibles, pas une erreur d’automatisation. La déconnexion masque les états d’exécution périmés. Aucun droit supplémentaire n’est accordé. Une erreur ignorée par <code>continue_on_error</code> peut manquer dans le résumé. L’API HA peut évoluer. Sources : <a href="https://www.home-assistant.io/docs/automation/basics/" target="_blank" rel="noreferrer">attributs</a>, <a href="https://github.com/home-assistant/core/blob/2026.10.4/homeassistant/components/trace/websocket_api.py" target="_blank" rel="noreferrer">API des traces</a>, <a href="https://github.com/home-assistant/core/blob/2026.10.4/homeassistant/components/trace/models.py" target="_blank" rel="noreferrer">schéma des résumés</a>.</p><h2 id="bubble-card-et-mushroom-une-seule-automatisation" tabindex="-1">Bubble Card et Mushroom : une seule automatisation <a class="header-anchor" href="#bubble-card-et-mushroom-une-seule-automatisation" aria-label="Permalink to &quot;Bubble Card et Mushroom : une seule automatisation&quot;">​</a></h2><p>Les fichiers <code>examples/bubble-single-readonly.yaml</code>, <code>bubble-single-control.yaml</code>, <code>mushroom-single-readonly.yaml</code> et <code>mushroom-single-control.yaml</code> visent chacun <strong>une automatisation</strong>. Remplacez <code>automation.replace_me</code> par son identifiant. Les exemples d’affichage désactivent les actions ; les exemples de commande utilisent l’action toggle habituelle de l’extension et son comportement standard. Ce sont des modèles YAML indépendants, pas une liste automatique ni du code d’extension supplémentaire. Le réglage <code>allow_toggle</code> de la carte principale n’agit pas sur ces cartes séparées.</p><p>Installez l’extension concernée séparément. Chemins sensibles à la casse :</p><ul><li>Bubble Card : <code>/hacsfiles/Bubble-Card/bubble-card.js</code></li><li>Mushroom : <code>/hacsfiles/lovelace-mushroom/mushroom.js</code></li></ul><p>Aucune carte existante n’est modifiée et aucun code tiers n’est inclus. <a href="https://github.com/Clooos/Bubble-Card" target="_blank" rel="noreferrer">Bubble Card</a> · <a href="https://github.com/piitaya/lovelace-mushroom" target="_blank" rel="noreferrer">Mushroom</a>.</p><h2 id="portee" tabindex="-1">Portée <a class="header-anchor" href="#portee" aria-label="Permalink to &quot;Portée&quot;">​</a></h2><p>La version publiée comprend le fichier JS compilé et un ZIP complet avec les instructions et exemples. Pour une mise à jour manuelle, conserver le chemin existant, actualiser <code>?v=0.1.3</code> et recharger complètement le navigateur. Node 22+ : <code>npm ci</code>, <code>npm run check</code>, <code>npm run build</code>, <code>npm test</code>. <a href="https://github.com/rockbaer2007/automation-status-card/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Vérifications</a>.</p><p>Licence MIT. Aucun service externe, identifiant d’accès ni télémétrie. HA enregistre la configuration du tableau de bord ; la carte ne modifie pas les définitions d’automatisations.</p><p><img src="`+a+'" alt="HA test: run warning and failure"></p><p><img src="'+s+'" alt="HA editor: selection"></p><p><img src="'+n+'" alt="Single-automation examples, initial-version test"></p>',35)])])}const A=i(c,[["render",u]]);export{v as __pageData,A as default};
